<template><el-dialog :model-value="store.isOpen" title="变更用户分组" width="min(520px, 92vw)" trap-focus :close-on-click-modal="false" @open="onOpen" @open-auto-focus="focusFirst" @close="requestClose" @closed="onClosed" @keydown.esc="requestClose"><template v-if="store.target"><el-alert v-if="store.state==='conflict'" ref="errorAlert" tabindex="-1" type="warning" :closable="false" title="用户信息已变化，正在刷新，请重新确认。"/><el-alert v-else-if="store.failureCode" ref="errorAlert" tabindex="-1" type="error" :closable="false" title="请求无法完成，请重新确认后重试。"/><el-form id="admin-user-group-change-form" ref="formRef" :model="form" :rules="rules" label-position="top" scroll-to-error @submit.prevent="submit"><el-form-item prop="groupGuid" :label="`当前分组：${store.target.group}`"><el-select ref="selectInput" v-model="form.groupGuid" :loading="store.groupsLoading" :disabled="busy||store.groupsError" placeholder="选择新分组"><el-option v-for="group in store.groups" :key="group.guid" :label="group.displayName" :value="group.guid" :disabled="group.key===store.target.group"/></el-select><p v-if="store.groupsError" role="alert">分组目录暂不可用。<el-button link type="primary" :disabled="store.groupsLoading" @click="store.retryGroups(props.owner)">重试加载</el-button></p></el-form-item><el-form-item prop="reason" label="变更原因"><el-input v-model="form.reason" type="textarea" :rows="3" :disabled="busy"/></el-form-item></el-form></template><template #footer><el-button @click="requestClose">取消</el-button><el-button type="primary" native-type="submit" form="admin-user-group-change-form" :loading="busy" :disabled="busy||store.groupsLoading||store.groupsError">确认变更</el-button></template></el-dialog></template>
<script setup>
import{computed,nextTick,reactive,ref,watch}from'vue';import{useAdminUserGroupChangeStore}from'@/stores/admin-user-group-change';import{normalizeGroupChangeRequest}from'@/api/admin-user-entitlements';const props=defineProps({owner:{type:Object,default:null}}),emit=defineEmits(['closed','succeeded','conflict','failed']),store=useAdminUserGroupChangeStore(),formRef=ref(null),selectInput=ref(null),errorAlert=ref(null),form=reactive({groupGuid:null,reason:''});let visibleOwner=null,closingOwner=null;const busy=computed(()=>store.state==='submitting');const rules={groupGuid:[{required:true,message:'请选择新分组',trigger:'change'}],reason:[{validator:(_r,_v,d)=>{const n=[...form.reason.trim()].length;n>=1&&n<=200?d():d(new Error('请输入 1–200 个字符的原因'))},trigger:['blur','change']}]};function clear(){form.groupGuid=null;form.reason='';formRef.value?.clearValidate?.()}function focusFirst(e){e?.preventDefault?.();const t=props.owner;nextTick(()=>nextTick(()=>{if(store.owns(t))selectInput.value?.focus?.()}))}function onOpen(){visibleOwner=props.owner;clear();focusFirst()}function requestClose(){if(store.owns(props.owner)){closingOwner=props.owner;store.close(props.owner)}}function onClosed(){const t=closingOwner??visibleOwner;closingOwner=null;if(store.isOpen)return;visibleOwner=null;clear();emit('closed',t)}async function submit(){const t=props.owner;if(!store.owns(t)||busy.value)return;if(['failed','conflict'].includes(store.state))store.reset(t);try{await formRef.value.validate()}catch{return}let input;try{input=normalizeGroupChangeRequest({targetGuid:store.target.guid,groupGuid:form.groupGuid,reason:form.reason,expectedAuthVersion:store.target.authVersion})}catch{return}const r=await store.submit(t,{groupGuid:input.groupGuid,reason:input.reason});if(!store.owns(t)||!r)return;if(r.state==='succeeded'){emit('succeeded',r.user,t);requestClose()}else if(r.state==='conflict')emit('conflict',t);else{emit('failed',r.failureCode,t);nextTick(()=>errorAlert.value?.$el?.focus?.())}}watch(()=>store.dialogRevision,()=>{if(store.isOpen)onOpen()});watch(()=>store.isOpen,(v,o)=>{if(!v&&o&&!closingOwner)closingOwner=visibleOwner??props.owner},{flush:'sync'})
</script>
